namespace sv_77c12a00c7af43d5becb716f3658c24b.Services;

/// <summary>
/// Mutable form models for two-way binding in the multi-step form.
/// </summary>
public class PersonalInfoModel
{
    public string FullName { get; set; } = string.Empty;
    public string Email { get; set; } = string.Empty;
    public string Phone { get; set; } = string.Empty;
    public string Address { get; set; } = string.Empty;
}

public class WorkEntryModel
{
    public string Company { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public DateTime StartDate { get; set; } = DateTime.Today;
    public DateTime? EndDate { get; set; }
    public bool IsCurrent { get; set; }
    public string Description { get; set; } = string.Empty;
}

public class ReferenceModel
{
    public string Name { get; set; } = string.Empty;
    public string Relationship { get; set; } = string.Empty;
    public string Email { get; set; } = string.Empty;
    public string Phone { get; set; } = string.Empty;
}

@namespace sv_77c12a00c7af43d5becb716f3658c24b.Components.Pages.Apply

<nav class="step-indicator" aria-label="Application progress">
    @for (int i = 0; i < StepNames.Count; i++)
    {
        var stepIndex = i;
        var cssClass = GetStepClass(stepIndex);
        <button class="step @cssClass"
                disabled="@(!IsStepClickable(stepIndex))"
                @onclick="() => OnStepClicked(stepIndex)"
                aria-current="@(stepIndex == CurrentStep ? "step" : null)">
            <span class="step-number">
                @if (stepIndex < CurrentStep)
                {
                    <span class="checkmark">&#10003;</span>
                }
                else
                {
                    @(stepIndex + 1)
                }
            </span>
            <span class="step-label">@StepNames[stepIndex]</span>
        </button>
        @if (i < StepNames.Count - 1)
        {
            <span class="step-connector @(i < CurrentStep ? "completed" : "")"></span>
        }
    }
</nav>

@code {
    [Parameter, EditorRequired] public int CurrentStep { get; set; }
    [Parameter, EditorRequired] public EventCallback<int> OnNavigateToStep { get; set; }

    private static readonly List<string> StepNames = new()
    {
        "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"
    };

    private string GetStepClass(int step)
    {
        if (step == CurrentStep) return "active";
        if (step < CurrentStep) return "completed";
        return "future";
    }

    private bool IsStepClickable(int step) => step < CurrentStep;

    private async Task OnStepClicked(int step)
    {
        if (IsStepClickable(step))
        {
            await OnNavigateToStep.InvokeAsync(step);
        }
    }
}

@namespace sv_77c12a00c7af43d5becb716f3658c24b.Components.Pages.Apply
@using sv_77c12a00c7af43d5becb716f3658c24b.Services

<div class="reference-form">
    <div class="form-row">
        <div class="form-group">
            <label>Name</label>
            <input type="text" @bind="Reference.Name" placeholder="Reference name" />
        </div>
        <div class="form-group">
            <label>Relationship</label>
            <input type="text" @bind="Reference.Relationship" placeholder="e.g., Former Manager" />
        </div>
    </div>
    <div class="form-row">
        <div class="form-group">
            <label>Email</label>
            <input type="email" @bind="Reference.Email" placeholder="email@example.com" />
        </div>
        <div class="form-group">
            <label>Phone</label>
            <input type="tel" @bind="Reference.Phone" placeholder="(555) 123-4567" />
        </div>
    </div>
    @if (CanRemove)
    {
        <button class="btn-remove" @onclick="OnRemove">Remove</button>
    }
</div>

@code {
    [Parameter, EditorRequired] public ReferenceModel Reference { get; set; } = default!;
    [Parameter] public bool CanRemove { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }
}

