        }
    </div>
    <div class="form-group">
        <label>Phone *</label>
        <input type="tel" @bind="Model.Phone" placeholder="(555) 123-4567" />
    </div>
    <div class="form-group">
        <label>Address *</label>
        <textarea @bind="Model.Address" rows="2" placeholder="Your full address"></textarea>
    </div>

