@namespace sv_77c12a00c7af43d5becb716f3658c24b.Components.Pages.Apply
@using sv_77c12a00c7af43d5becb716f3658c24b.Services

<div class="step-content">
    <h2>References</h2>
    <p class="step-description">Please provide 2-3 professional references.</p>

    @for (int i = 0; i < References.Count; i++)
    {
        var index = i;
        <div class="entry-card">
            <h4>Reference @(index + 1)</h4>
            <ReferenceForm Reference="References[index]"
                           CanRemove="References.Count > 2"
                           OnRemove="() => RemoveReference(index)" />
        </div>
    }

    @if (References.Count < 3)
    {
        <button class="btn-secondary" @onclick="AddReference">+ Add Reference</button>
    }

    @if (!string.IsNullOrEmpty(ValidationError))
    {
        <div class="validation-error">@ValidationError</div>
    }

    <div class="step-buttons">
        <button class="btn-outline" @onclick="OnBack">Back</button>
        <button class="btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public List<ReferenceModel> References { get; set; } = default!;
    [Parameter, EditorRequired] public EventCallback OnNext { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }

    private string? ValidationError;

    private void AddReference()
    {
        if (References.Count < 3)
        {
            References.Add(new ReferenceModel());
        }
    }

    private void RemoveReference(int index)
    {
        if (References.Count > 2)
        {
            References.RemoveAt(index);
        }
    }

    private async Task HandleNext()
    {
        ValidationError = null;

        foreach (var r in References)
        {
            if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Email))
            {
                ValidationError = "Each reference requires at least a name and email.";
                return;
            }
        }

        await OnNext.InvokeAsync();
    }
}

