+    text-align: right;
+    font-size: 0.85rem;
+    color: #888;
+    margin-top: 0.4rem;
+}
+
+.char-count.over-limit {
+    color: #e74c3c;
+    font-weight: 600;
+}
+
+/* Validation */
+.validation-error {
+    background: #fef2f2;
+    border: 1px solid #fecaca;
+    color: #dc2626;
+    padding: 0.8rem 1rem;
+    border-radius: 6px;
+    margin-top: 1rem;
+    font-size: 0.9rem;
+}
+
+.field-error {
+    color: #dc2626;
+    font-size: 0.8rem;
+    margin-top: 0.3rem;
+    display: block;
+}
+
+/* Review Step */
+.review-section {
+    border: 1px solid #eee;
+    border-radius: 6px;
+    padding: 1.2rem;
+    margin-bottom: 1rem;
+}
+
+.review-header {
+    display: flex;
+    justify-content: space-between;
+    align-items: center;
+    margin-bottom: 0.8rem;
+}
+
+.review-header h3 {
+    margin: 0;
+    font-size: 1rem;
+    color: #333;
+}
+
+.review-section dl {
+    display: grid;
+    grid-template-columns: 100px 1fr;
+    gap: 0.4rem 1rem;
+    margin: 0;
+}
+
+.review-section dt {
+    font-weight: 500;
+    color: #666;
+    font-size: 0.9rem;
+}
+
+.review-section dd {
+    margin: 0;
+    font-size: 0.9rem;
+}
+
+.review-entry {
+    padding: 0.6rem 0;
+    border-bottom: 1px solid #f0f0f0;
+    font-size: 0.9rem;
+}
+
+.review-entry:last-child {
+    border-bottom: none;
+}
+
+.review-dates {
+    color: #888;
+    font-size: 0.85rem;
+}
+
+.review-description {
+    color: #555;
+    font-size: 0.85rem;
+    margin: 0.3rem 0 0 0;
+}
+
+.review-cover-letter {
+    white-space: pre-wrap;
+    font-size: 0.9rem;
+    color: #444;
+    line-height: 1.6;
+}
+
+/* Submission Confirmation */
+.submission-confirmation {
+    text-align: center;
+    padding: 3rem 1rem;
+}
+
+.submission-confirmation h3 {
+    color: #2ecc71;
+    font-size: 1.5rem;
+    margin-bottom: 1rem;
+}
+
+.submission-confirmation p {
+    color: #555;
+    font-size: 1.1rem;
+}
+
+/* Responsive */
+@media (max-width: 600px) {
+    .form-row {
+        grid-template-columns: 1fr;
+    }
+
+    .step-indicator {
+        flex-wrap: wrap;
+    }
+
+    .step-label {
+        display: none;
+    }
+}
+

